create table d_ref_instrument(key_instrument_id string comment '证券内码 ',ins_sht_desc string comment '证券简称 ',ins_lng_desc string comment '证券全名 ',data_source string comment '数据来源（见字典表） ',updated_datetime string comment '更新时间 ',ins_family string comment '证券集 字典项= INSTRUMENTFAMILY',exch_market string comment '交易所 ',currency string comment '币种 ',description string comment '证券描述 ',issuer_id string comment '发行人 ',maturity_date string comment '到期日 ',created_datetime string comment '创建日期 ',created_by string comment '创建人 ',wind_code string comment 'WIND代码 ',is_underlying_visible string comment '是否可见穿透持仓',data_time string comment '数据时间',base_underlying_ins_id string comment '基础证券内码(GDR)',transform_proportion string comment '转换比例(GDR)',ins_subtype string comment '产品子类',summary_mapping string comment '标的汇总分类',industry_name string comment '行业信息',industry_code string comment '行业code',per_unit string comment '【AI】每单位',ins_eng_desc string comment '标的英文名称') partitioned by (busi_date string comment '业务日期') row format delimited fields terminated by ',' stored as textfile;
